<?php use yii\helpers\Html;$this->title=$title;?><div class="toolbar"><?php if($title==='Audit Log'):?><form><input name="q" value="<?=Html::encode(Yii::$app->request->get('q'))?>" placeholder="Search user, record, or module"><button>Search</button></form><?php endif?></div><section class="panel tablepanel"><div class="panelhead"><h3><?=count($rows)?> records shown</h3></div><div class="scroll"><table><?php if($rows):?><thead><tr><?php foreach(array_keys($rows[0]) as $k):if($k==='id')continue;?><th><?=Html::encode(ucwords(str_replace('_',' ',$k)))?></th><?php endforeach?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $k=>$v):if($k==='id')continue;?><td><?=Html::encode($v)?></td><?php endforeach?></tr><?php endforeach?></tbody><?php else:?><tbody><tr><td>No records yet.</td></tr></tbody><?php endif?></table></div></section>
